package br.com.onda;
import org.json.*;
import java.util.*;
/** Bounded local references and annotations. It never stores media bytes or network URLs. */
final class MediaShelf {
 static final int ITEMS=200,COLLECTIONS=30,PER_COLLECTION=50,NOTES=10,MAX_JSON=1048576;
 static final class Note {String id,text;long at;Note(String id,long at,String text){this.id=id;this.at=at;this.text=text;}}
 static final class Item {String id,type,uri,title;long position,duration,seen;final List<Note> notes=new ArrayList<>();}
 static final class Collection {String id,name;final List<String> items=new ArrayList<>();}
 final LinkedHashMap<String,Item> items=new LinkedHashMap<>();final LinkedHashMap<String,Collection> collections=new LinkedHashMap<>();boolean valid=true;
 static boolean source(String type,String uri){return Arrays.asList("audio","video","pdf").contains(type)&&uri!=null&&uri.length()<=4096&&(uri.startsWith("content://")||uri.startsWith("file://"));}
 static String clean(String s,int max){return s==null?"":s.trim().substring(0,Math.min(max,s.trim().length()));}
 Item touch(String type,String uri,String title,long at,long duration,long now){if(!valid||!source(type,uri))return null;Item item=null;for(Item i:items.values())if(i.type.equals(type)&&i.uri.equals(uri)){item=i;break;}
  if(item==null){if(items.size()>=ITEMS){Item oldest=null;for(Item i:items.values())if(i.notes.isEmpty()&&!pinned(i.id)&&(oldest==null||i.seen<oldest.seen))oldest=i;if(oldest==null)return null;items.remove(oldest.id);}item=new Item();item.id=UUID.randomUUID().toString();item.type=type;item.uri=uri;item.title="Arquivo local";items.put(item.id,item);}
  String label=clean(title,200);if(!label.isEmpty())item.title=label;long max="pdf".equals(type)?5000:VideoLoop.MAX_TIME;if(duration>0)item.duration=Math.min(max,duration);item.position=Math.max(0,Math.min("pdf".equals(type)?4999:VideoLoop.MAX_TIME,at));if(item.duration>0){if("pdf".equals(type))item.position=Math.min(item.position,item.duration-1);else if(item.position>=item.duration-500)item.position=0;}item.seen=Math.max(0,now);return item;
 }
 boolean pinned(String id){for(Collection c:collections.values())if(c.items.contains(id))return true;return false;}
 Collection create(String name){String label=clean(name,60);if(!valid||label.isEmpty()||collections.size()>=COLLECTIONS)return null;Collection c=new Collection();c.id=UUID.randomUUID().toString();c.name=label;collections.put(c.id,c);return c;}
 boolean hide(String id){Item i=items.get(id);if(i==null||(!i.notes.isEmpty()&&!pinned(id)))return false;i.seen=0;return true;}
 private void reveal(Item i,long now){if(i!=null&&i.seen==0&&!i.notes.isEmpty()&&!pinned(i.id))i.seen=Math.max(1,now);}
 boolean removeFrom(String collection,String id,long now){Collection c=collections.get(collection);if(c==null||!c.items.remove(id))return false;reveal(items.get(id),now);return true;}
 boolean removeCollection(String id,long now){Collection c=collections.remove(id);if(c==null)return false;for(String key:c.items)reveal(items.get(key),now);return true;}
 boolean add(String collection,String item){Collection c=collections.get(collection);if(c==null||!items.containsKey(item))return false;if(c.items.contains(item))return true;if(c.items.size()>=PER_COLLECTION)return false;c.items.add(item);return true;}
 boolean note(String item,String id,long at,String text){Item i=items.get(item);String body=clean(text,1000);if(i==null||body.isEmpty()||at<0||at>(i.type.equals("pdf")?4999:VideoLoop.MAX_TIME)||(i.duration>0&&at>=(i.type.equals("pdf")?i.duration:i.duration+1)))return false;for(Note n:i.notes)if(n.id.equals(id)){n.text=body;return true;}if(i.notes.size()>=NOTES)return false;i.notes.add(new Note(UUID.randomUUID().toString(),at,body));return true;}
 List<Item> recent(){List<Item> result=new ArrayList<>();for(Item i:items.values())if(i.seen>0)result.add(i);result.sort((a,b)->Long.compare(b.seen,a.seen));return result;}
 String encode(){try{JSONArray entries=new JSONArray(),groups=new JSONArray();for(Item i:items.values()){JSONArray notes=new JSONArray();for(Note n:i.notes)notes.put(new JSONObject().put("id",n.id).put("at",n.at).put("text",n.text));entries.put(new JSONObject().put("id",i.id).put("type",i.type).put("uri",i.uri).put("title",i.title).put("position",i.position).put("duration",i.duration).put("seen",i.seen).put("notes",notes));}for(Collection c:collections.values())groups.put(new JSONObject().put("id",c.id).put("name",c.name).put("items",new JSONArray(c.items)));return new JSONObject().put("v",1).put("items",entries).put("collections",groups).toString();}catch(JSONException e){throw new IllegalStateException(e);}}
 static MediaShelf decode(String raw){MediaShelf s=new MediaShelf();try{if(raw==null||raw.length()>MAX_JSON)throw new JSONException("size");JSONObject root=new JSONObject(raw);if(root.optInt("v",1)!=1)throw new JSONException("version");JSONArray items=root.optJSONArray("items"),groups=root.optJSONArray("collections");if(items!=null){if(items.length()>ITEMS)throw new JSONException("items");for(int k=0;k<items.length();k++){JSONObject o=items.getJSONObject(k);Item i=new Item();i.id=o.getString("id");i.type=o.getString("type");i.uri=o.getString("uri");if(i.id.length()>80||!source(i.type,i.uri)||s.items.containsKey(i.id))throw new JSONException("item");i.title=clean(o.optString("title","Arquivo local"),200);i.duration=Math.max(0,Math.min(i.type.equals("pdf")?5000:VideoLoop.MAX_TIME,o.optLong("duration")));i.position=Math.max(0,Math.min(i.type.equals("pdf")?4999:VideoLoop.MAX_TIME,o.optLong("position")));i.seen=Math.max(0,o.optLong("seen"));JSONArray notes=o.optJSONArray("notes");if(notes!=null){if(notes.length()>NOTES)throw new JSONException("notes");for(int n=0;n<notes.length();n++){JSONObject note=notes.getJSONObject(n);String text=clean(note.optString("text"),1000);long at=note.optLong("at",-1);if(text.isEmpty()||at<0||at>(i.type.equals("pdf")?4999:VideoLoop.MAX_TIME))throw new JSONException("note");i.notes.add(new Note(clean(note.getString("id"),80),at,text));}}s.items.put(i.id,i);}}
   if(groups!=null){if(groups.length()>COLLECTIONS)throw new JSONException("collections");for(int k=0;k<groups.length();k++){JSONObject o=groups.getJSONObject(k);Collection c=new Collection();c.id=o.getString("id");c.name=clean(o.getString("name"),60);if(c.id.length()>80||c.name.isEmpty()||s.collections.containsKey(c.id))throw new JSONException("collection");JSONArray ids=o.getJSONArray("items");if(ids.length()>PER_COLLECTION)throw new JSONException("size");for(int n=0;n<ids.length();n++){String id=ids.getString(n);if(s.items.containsKey(id)&&!c.items.contains(id))c.items.add(id);}s.collections.put(c.id,c);}}
  }catch(Exception e){s.items.clear();s.collections.clear();s.valid=false;}return s;
 }
}
